mapper.select:
SELECT COUNT(*)
FROM tbl_print_order
WHERE email = #{email}

mapper.update:
UPDATE tbl_print_order
SET status = #{status}, payment_key = #{paymentKey}
WHERE order_id = #{orderId}

mapper.delete:
DELETE FROM tbl_print_order_item
WHERE order_no IN (
SELECT order_no FROM tbl_print_order WHERE baby_no = #{babyNo}
)
